constexpr U MOD=(U(1)<<61)-1;
std::array<unsigned char,32>digest(const std::string&s){std::array<unsigned char,32>r{};SHA256(reinterpret_cast<const unsigned char*>(s.data()),s.size(),r.data());return r;}
std::string hex(const std::array<unsigned char,32>&d){std::ostringstream s;for(unsigned x:d)s<<std::hex<<std::setfill('0')<<std::setw(2)<<x;return s.str();}
U splitmix(U&s){U z=(s+=0x9E3779B97F4A7C15ULL);z=(z^(z>>30))*0xBF58476D1CE4E5B9ULL;z=(z^(z>>27))*0x94D049BB133111EBULL;return z^(z>>31);}
int degree(const json&e){std::string op=e["op"];if(op=="var")return 1;if(op=="const")return 0;if(op=="neg")return degree(e["args"]);int d=0;for(const auto&a:e["args"]){if(op=="add")d=std::max(d,degree(a));else if(op=="mul")d+=degree(a);else throw std::runtime_error("unknown expression op");}return d;}
U eval(const json&e,const std::map<std::string,U>&env){std::string op=e["op"];if(op=="var")return env.at(e["args"].get<std::string>());if(op=="const"){int64_t v=e["args"].get<int64_t>();return v>=0?U(v)%MOD:sub(0,U(-v)%MOD,MOD);}if(op=="neg")return sub(0,eval(e["args"],env),MOD);U r=op=="add"?0:1;for(const auto&a:e["args"]){U x=eval(a,env);r=op=="add"?add(r,x,MOD):mul(r,x,MOD);}return r;}
std::string values(const json&s,const std::string&id,U seed,const std::string&domain,int n){std::string material=id;for(int i=0;i<8;i++)material.push_back(char(seed>>(8*i)));material+=domain;auto h=digest(material);U state=0;for(int i=0;i<8;i++)state|=U(h[i])<<(8*i);std::string bytes;for(int i=0;i<n;i++){std::map<std::string,U>env;for(const auto&v:s["variables"])env[v.get<std::string>()]=splitmix(state)%MOD;U a=eval(s["lhs"],env),b=eval(s["rhs"],env);need(a==b,"identity counterexample at "+std::to_string(i));for(int k=0;k<8;k++)bytes.push_back(char(a>>(8*k)));}return hex(digest(bytes));}
void check(const json&c){need(c["schema"]=="identity.certificate/v1"&&val(c["modulus"])==MOD,"certificate schema/modulus");const auto&s=c["statement"];need(val(s["degree_bound"])>=U(std::max(degree(s["lhs"]),degree(s["rhs"]))),"degree bound");std::string id="IDC1h"+hex(digest(s.dump())).substr(0,16);need(c["id"]==id,"certificate id");need(val(c["points"])>0,"zero points");need(c["value_digest"]==values(s,id,val(c["seed"]),"cert",int(val(c["points"]))),"value digest");values(s,id,20261017,"extra",32);}
json var(const std::string&n){return{{"op","var"},{"args",n}};}json constant(int v){return{{"op","const"},{"args",v}};}json neg(const json&a){return{{"op","neg"},{"args",a}};}json sum(std::initializer_list<json>a){return{{"op","add"},{"args",json(a)}};}json product(std::initializer_list<json>a){return{{"op","mul"},{"args",json(a)}};}json pow_expr(const json&a,int n){json xs=json::array();for(int i=0;i<n;i++)xs.push_back(a);return{{"op","mul"},{"args",xs}};}
